interface Greeter {
    fun greet(): String
    fun twice(): String = greet() + greet()
}

class Base : Greeter {
    override fun greet() = "hi"
}

class Loud(b: Greeter) : Greeter by b {
    override fun greet() = "HI"
}

fun main() {
    val l = Loud(Base())
    println("${l.greet()} ${l.twice()}")
}
